cultures_path = os.path.join(os.path.dirname(__file__), '../data/cultures.json')
with open(cultures_path, 'r', encoding='utf-8') as f:
    data = json.load(f)

matched = 0
for culture in data['cultures']:
    extra = enrichment.get(culture['slug'])
    if not extra:
        print(f"No enrichment for: {culture['slug']}")
        continue
    culture.update(extra)
    matched += 1

print(f"Enriched {matched}/{len(data['cultures'])} cultures.")
with open(cultures_path, 'w', encoding='utf-8') as f:
    json.dump(data, f, indent=2, ensure_ascii=False)
print("cultures.json updated successfully.")
